import heapq

def solve(n, edges, source, target):
    # Standard Min-Heap Dijkstra
    adj = {i: [] for i in range(n)}
    for u, v, w in edges:
        if u < n and v < n:
            adj[u].append((v, w))

    dist = {i: float('inf') for i in range(n)}
    dist[source] = 0
    pq = [(0, source)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u == target:
            return int(d)

        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    return int(dist[target]) if dist[target] != float('inf') else -1

from collections import deque

def solve(n, edges, source, target):
    # Naive Unweighted BFS (Fails on Weighted Graphs)
    adj = {i: [] for i in range(n)}
    for u, v, w in edges:
        if u < n and v < n:
            adj[u].append(v)

    visited = {source: 0}
    q = deque([source])

    while q:
        u = q.popleft()
        if u == target:
            return visited[u]
        for v in adj[u]:
            if v not in visited:
                visited[v] = visited[u] + 1
                q.append(v)

    return -1

import heapq

def solve(n, edges, source, target):
    if source == target:
        return 0
    adj_f = {i: [] for i in range(n)}
    adj_b = {i: [] for i in range(n)}
    for u, v, w in edges:
        if u < n and v < n:
            adj_f[u].append((v, w))
            adj_b[v].append((u, w))

    dist_f = {i: float('inf') for i in range(n)}
    dist_b = {i: float('inf') for i in range(n)}
    dist_f[source] = 0
    dist_b[target] = 0

    pq_f = [(0, source)]
    pq_b = [(0, target)]
    mu = float('inf')

    while pq_f and pq_b:
        df, u = heapq.heappop(pq_f)
        if df <= dist_f[u]:
            for v, w in adj_f[u]:
                if dist_f[u] + w < dist_f[v]:
                    dist_f[v] = dist_f[u] + w
                    heapq.heappush(pq_f, (dist_f[v], v))
                if dist_b[v] != float('inf'):
                    mu = min(mu, dist_f[u] + w + dist_b[v])

        db, u = heapq.heappop(pq_b)
        if db <= dist_b[u]:
            for v, w in adj_b[u]:
                if dist_b[u] + w < dist_b[v]:
                    dist_b[v] = dist_b[u] + w
                    heapq.heappush(pq_b, (dist_b[v], v))
                if dist_f[v] != float('inf'):
                    mu = min(mu, dist_b[u] + w + dist_f[v])

        if min(pq_f[0][0] if pq_f else float('inf'), pq_b[0][0] if pq_b else float('inf')) >= mu:
            break

    return int(mu) if mu != float('inf') else -1

def solve(n, edges, source, target):
    # Dial's Algorithm with Integer Buckets
    adj = {i: [] for i in range(n)}
    max_w = 1
    for u, v, w in edges:
        if u < n and v < n:
            adj[u].append((v, w))
            max_w = max(max_w, w)

    max_dist = n * max_w + 1
    buckets = [[] for _ in range(max_dist + 1)]
    dist = [float('inf')] * n

    dist[source] = 0
    buckets[0].append(source)
    idx = 0

    while idx <= max_dist:
        while buckets[idx]:
            u = buckets[idx].pop()
            if idx > dist[u]:
                continue
            if u == target:
                return idx
            for v, w in adj[u]:
                new_d = dist[u] + w
                if new_d < dist[v]:
                    dist[v] = new_d
                    if new_d <= max_dist:
                        buckets[new_d].append(v)
        idx += 1

    return int(dist[target]) if dist[target] != float('inf') else -1
